    var source__4 string = "package io;\n\nuse std::bytes;\nuse std::internal::host;\n\npub fn print[T: ToString](value: T) -> unit {\n    host::print(ToString::to_string(value))\n}\n\npub fn println[T: ToString](value: T) -> unit {\n    host::println(ToString::to_string(value))\n}\n\npub fn eprint[T: ToString](value: T) -> unit {\n    host::eprint(ToString::to_string(value))\n}\n\npub fn eprintln[T: ToString](value: T) -> unit {\n    host::eprint(ToString::to_string(value) + \"\\n\")\n}\n\npub fn read_stdin() -> Result[bytes::Bytes, string] {\n    let (ok, data, err) = host::read_stdin();\n    if ok {\n        Result::Ok(bytes::Bytes::from_vec(data))\n    } else {\n        Result::Err(err)\n    }\n}\n\npub fn write_stdout(data: bytes::Bytes) -> Result[unit, string] {\n    let (ok, err) = host::write_stdout(data.to_vec());\n    if ok {\n        Result::Ok(())\n    } else {\n        Result::Err(err)\n    }\n}\n\npub fn write_stderr(data: bytes::Bytes) -> Result[unit, string] {\n    let (ok, err) = host::write_stderr(data.to_vec());\n    if ok {\n        Result::Ok(())\n    } else {\n        Result::Err(err)\n    }\n}\n\npub fn read_stdin_exact(length: int) -> Result[bytes::Bytes, string] {\n    if length < 0 {\n        Result::Err(\"read length must be non-negative\")\n    } else {\n        let (ok, data, err) = host::read_stdin_exact(length);\n        if ok {\n            Result::Ok(bytes::Bytes::from_vec(data))\n        } else {\n            Result::Err(err)\n        }\n    }\n}"
